import { redirect } from "@sveltejs/kit";
import { g as getSessionCookie, D as deleteSession, t as SESSION_COOKIE_NAME } from "../../../chunks/db.js";
const actions = {
  default: async ({ cookies, request, platform }) => {
    const db = platform?.env?.DB;
    const token = getSessionCookie(request.headers.get("cookie"));
    if (db && token) {
      try {
        await deleteSession(db, token);
      } catch (err) {
        console.error("Kunne ikke slette session:", err);
      }
    }
    cookies.delete(SESSION_COOKIE_NAME, { path: "/" });
    redirect(303, "/");
  }
};
export {
  actions
};
